import {pairView,pairCounts,pairTheory,pairRemaining,pairTallies,pairBranch,startPairs,setPairPage,setPairMode,beginPairRun,selectPairRun,choosePairPrediction,drawPairFirst,drawPairSecond,selectPairTask,setPairDraft,checkPair,pairHelp,advancePairLearn,setPairFolded,choosePairBranch,notePairSupport,selectPairCheck,selectedPairCheck,randomPairIndex} from './seed-pairs-core.mjs';
import {hearButton,stopSpeech} from './play-media.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const markName=(x,labels={sun:'Sun',moon:'Moon'})=>labels?.[x]||'Waiting';
const markIcon=x=>x==='sun'?'☼':x==='moon'?'☾':'?';
const category={ss:'Two suns',mixed:'One of each',mm:'Two moons'};
const ruleName=m=>m==='keep'?'Keep the first out':'Put it back';
const button=(attr,label,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attr}>${esc(label)}</button>`;
const text=t=>`<p>${esc(t)}</p>`;
const lines=ls=>(ls||[]).map(l=>text(l.text)).join('');
export const pairsEntry=()=>'<aside class="pairs-entry"><a class="secondary" href="#numbers/seeds/pairs">Keep it out: draw two seeds</a><p>Does the second seed’s chance change when the first one stays out?</p></aside>';
function bag(slots,available=null,labels={sun:'Sun',moon:'Moon'},tree=null){const present=available??slots.map((_,i)=>i),counts=pairCounts(present.map(i=>slots[i]));return `<div class="pairs-bag-wrap"><div class="pairs-bag" ${tree?`data-pair-tree-bag="${tree}"`:'data-pair-bag'} role="img" aria-label="Available for the next draw: ${counts.sun} ${esc(labels.sun)} and ${counts.moon} ${esc(labels.moon)} counters.">${slots.map((m,i)=>`<span class="pairs-seed pairs-${m}${present.includes(i)?'':' pairs-out'}" ${tree?'data-pair-tree-slot':'data-pair-slot'}="${i}" data-mark="${m}" data-available="${present.includes(i)}" aria-hidden="true">${present.includes(i)?markIcon(m):'·'}</span>`).join('')}</div><p><strong>${counts.sun} ${esc(labels.sun)} + ${counts.moon} ${esc(labels.moon)}</strong><br>${present.length} available positions</p></div>`;}
function tray(stage,slot,slots,label,labels={sun:'Sun',moon:'Moon'}){const m=slot===null||slot===undefined?null:slots[slot];return `<div class="pairs-tray" data-pair-tray="${stage}" data-mark="${m||'none'}"><strong>${stage==='first'?'First seed':'Second seed'}</strong><span class="pairs-seed ${m?'pairs-'+m:'pairs-waiting'}" aria-hidden="true">${markIcon(m)}</span><span>${esc(markName(m,labels))}</span>${label?`<small>${esc(label)}</small>`:''}</div>`;}
function modeButtons(r){return `<div class="pairs-modes" role="group" aria-label="Choose a draw rule">${['keep','return'].map(m=>button(`data-pair-mode="${m}" aria-pressed="${r.mode===m}"`,ruleName(m),r.mode===m)).join('')}</div>`;}
function drawPage(v){const r=v.root,s=v.source,run=v.current,counts=pairCounts(s.slots),remaining=pairRemaining(s.slots,r.mode,run?.pending??null),last=run?.pairs.at(-1),pending=run?.pending??null,waiting=v.readableRuns.find(x=>x.entry.mode===r.mode&&x.entry.pairs.length<15)?.entry;
 const first=pending??last?.first??null,second=pending!==null?null:last?.second??null;
 const completed=run?.pairs.length||0,modeRuns=v.readableRuns.filter(x=>x.entry.mode===r.mode);
 return `<h2 id="pair-question" tabindex="-1">${!run?'Try a two-seed draw':pending!==null?'What is left for the second draw?':completed===15?'This set of 15 is recorded':'Draw the first seed'}</h2><p class="pairs-rule">${esc(s.rules[r.mode])}</p><div class="pairs-apparatus">${bag(s.slots,remaining.indices,s.labels)}<div><div class="pairs-trays">${tray('first',first,s.slots,pending!==null?(r.mode==='keep'?'Kept outside the bag':'Returned before draw two'):'',s.labels)}${tray('second',second,s.slots,'',s.labels)}</div><p class="pairs-step">${pending!==null?(r.mode==='keep'?'The first seed is out. Choose randomly from the five positions still in the bag.':'The first seed is back. All six positions are available again.'):last?`Previous pair, recorded. The bag is refilled: ${counts.sun} ${esc(s.labels.sun)} and ${counts.moon} ${esc(s.labels.moon)}, ready for the next trial.`:'The first tray is waiting. Each trial starts with the full pictured bag.'}</p></div></div>${run?`<p>Set ${modeRuns.findIndex(x=>x.entry.id===run.id)+1} of 3 with this rule · ${completed} of 15 complete pairs${pending!==null?' · first seed of the next pair kept':''}</p>`:''}
 ${!run||!completed&&pending===null?`<fieldset class="pairs-prediction"><legend>What might appear most often in 15 pairs?</legend><div class="pairs-choice-row">${['ss','mixed','mm','unsure','none'].map(k=>button(`data-pair-predict="${k}" aria-pressed="${(run?.prediction??'none')===k}"${!run?' disabled':''}`,category[k]||(k==='unsure'?'Not sure yet':'No prediction'))).join('')}</div><p>Optional and unscored. Start a set first; you can change your prediction until its first draw.</p></fieldset>`:`<p>Prediction before this set: <strong>${esc(category[run.prediction]||(run.prediction==='unsure'?'Not sure yet':'No prediction recorded'))}</strong>. This is a guess to compare, not a score.</p>`}
 <div class="pairs-main-action">${!run?button('data-pair-begin','Start 15 trials',true):pending!==null?button('data-pair-second',`Draw second seed from ${remaining.indices.length} positions`,true):completed<15?button('data-pair-first',`Draw first seed of trial ${completed+1}`,true):waiting&&waiting.id!==run.id?button('data-pair-resume','Return to the waiting set',true):modeRuns.length<3?button('data-pair-begin','Start another set of 15',true):'<p>All three sets with this rule are kept. Try the other rule, explore the tree, or return to a question.</p>'}</div>${run?`<p class="pairs-count-note">Only complete pairs enter the tally. A first seed waiting for its partner is not a completed trial.</p>`:''}<div class="pairs-bottom-links">${button('data-pair-page="tree"','Explore the chance tree')}${button('data-pair-page="results"','Look at the results')}</div>`;
}
function branchExplorer(r){const s=r.source,b=pairBranch(r),counts=pairCounts(s.slots);return `<section class="pairs-tree-explorer"><h3>Choose a path, not a random trial</h3><p>This tree follows the experiment’s pictured bag (${counts.sun} sun, ${counts.moon} moon) and the rule <strong>${ruleName(r.mode)}</strong>. Choosing here adds no random result.</p><div class="pairs-branch-steps"><section><h4>Choose the first mark</h4>${bag(s.slots,null,s.labels,'first')}<div class="pairs-choice-row">${['sun','moon'].map(m=>button(`data-pair-branch-stage="first" data-pair-mark="${m}" aria-pressed="${r.branch.first===m}"${!counts[m]?' disabled':''}`,`Explore ${m} first`)).join('')}</div></section>${b&&b.firstNumerator>0?`<section><h4>Then choose the second mark</h4>${bag(s.slots,b.remaining.indices,s.labels,'remaining')}<p>After ${markName(b.first).toLowerCase()} first: ${b.remaining.counts.sun} sun and ${b.remaining.counts.moon} moon remain available.</p><div class="pairs-choice-row">${['sun','moon'].map(m=>button(`data-pair-branch-stage="second" data-pair-mark="${m}" aria-pressed="${r.branch.second===m}"`,`Then ${m}`)).join('')}</div></section>`:''}</div>${b?`<div class="pairs-branch" data-pair-branch><p>First ${markName(b.first).toLowerCase()}: <strong data-pair-first-fraction>${b.firstNumerator}/${b.firstDenominator}</strong>.</p>${b.firstNumerator===0?'<p>This first mark is absent, so this path cannot happen. There is no second-draw condition for it.</p>':b.second?`<p>Second ${markName(b.second).toLowerCase()}, after that first seed: <strong data-pair-second-fraction>${b.secondNumerator}/${b.secondDenominator}</strong>.</p><p class="pairs-equation" data-pair-path-fraction>${b.firstNumerator}/${b.firstDenominator} × ${b.secondNumerator}/${b.secondDenominator} = ${b.numerator}/${b.denominator}</p><p>${b.possible?'Both steps have to happen, so multiply along this path.':'This path cannot happen with this bag and rule.'}</p>`:'<p>Choose the second mark to finish this ordered path.</p>'}</div>`:'<p>First choose a mark above. The second chance depends on what came out and whether it went back.</p>'}</section>`;}
function questionBag(t,r){const c=pairCounts(t.slots),same=JSON.stringify(t.slots)===JSON.stringify(r.source.slots);return `<aside class="pairs-question-bag" data-pair-question-bag><strong>${same?'This question’s bag':'Separate question bag'}: ${c.sun} sun and ${c.moon} moon</strong><p>${t.mode==='compare'?'Compare keeping the first out with putting it back.':'Question rule: keep the first seed out, then refill before the next trial.'}</p>${!same?'<p>This question keeps its own bag; it does not use the changed experiment bag above.</p>':''}</aside>`;}
function learning(r,w){return `<section class="pairs-learning" data-pair-learning><h3>One idea at a time</h3>${r.folded?button('data-pair-fold="false"','Show me how'):`${lines(r.source.learn.slice(0,r.learnSeen))}${r.learnSeen<r.source.learn.length?button('data-pair-learn','Next teaching line'):''}${w?.source.guided.length?`<aside class="pairs-guided"><h4>A guided first question</h4>${lines(w.source.guided)}</aside>`:''}${button('data-pair-fold="true"','I know this, show me the question')}`}</section>`;}
function checkRecord(c,r){return `<article class="pairs-record" data-pair-record><h3>Kept question check</h3>${questionBag(c.source,r)}${text(c.source.prompt)}${text(c.feedback)}<p>Recorded result: <strong>${c.correct?'fits this question':'a different answer'}</strong>.</p><p>Recorded entry: ${esc(c.raw.join(' / '))}</p><div class="pairs-worked">${lines(c.source.worked)}</div></article>`;}
function question(v){const r=v.root,w=v.work;return `<section class="pairs-question" data-pair-question><label for="pair-task">Choose a question<select id="pair-task" data-pair-task>${v.tasks.map(t=>`<option value="${esc(t.id)}"${r.taskId===t.id?' selected':''}>${esc(t.title)}${t.unreadable?' · notes only':''}</option>`).join('')}</select></label>${!w?'<p>This earlier question cannot be opened here. Its data stays in your notes; another question and both draw rules are still available.</p><a href="#notes">Open notes</a>':`${questionBag(w.source,r)}<h3>${esc(w.source.prompt)}</h3>${w.source.kind==='choice'?`<div class="pairs-choice-row">${w.source.options.map(o=>button(`data-pair-option="${esc(o.id)}" aria-pressed="${w.draft[0]===o.id}"`,o.label)).join('')}</div>`:`<div class="pairs-fields">${w.draft.map((raw,i)=>`<label>${w.source.kind==='fraction'?(i===0?'Numerator: favorable outcomes':'Denominator: all outcomes'):[category.ss,category.mixed,category.mm][i]}<input type="text" inputmode="numeric" maxlength="4" autocomplete="off" spellcheck="false" data-pair-draft="${i}" value="${esc(raw)}"></label>`).join('')}</div><p>Use whole numbers. A fraction’s denominator must be greater than zero.</p>`}<p class="pairs-retention">The latest four checks stay here, plus your first kept check.${w.checks.length>=4?' The next check replaces the oldest of those four.':''}</p>${button('data-pair-check','Check this answer',true)}<div class="pairs-support-row">${button('data-pair-together'+(w.support.together?' disabled':''),w.support.together?'Working together recorded':'We’re working together')}<span data-pair-audio>${hearButton(w.source.prompt,'Hear this question','en')}</span></div>${w.checks.length||w.firstKept?`<label for="pair-kept">Look at a kept check<select id="pair-kept" data-pair-kept><option value="none"${w.checkView===null?' selected':''}>Back to this question</option><option value="latest"${w.checkView==='latest'?' selected':''}>Latest check</option>${w.firstKept?`<option value="first"${w.checkView==='first'?' selected':''}>First kept check</option>`:''}${w.checks.map((_,i)=>`<option value="${i}"${w.checkView===i?' selected':''}>Earlier check ${i+1}</option>`).join('')}</select></label>`:''}${w.checkView!==null&&selectedPairCheck(w)?checkRecord(selectedPairCheck(w),r):''}<section class="pairs-help" data-pair-help-box>${w.helpStage===1?`<h4>A hint</h4>${text(w.source.hint)}`:w.helpStage===2?`<h4>A different worked example</h4>${lines(w.source.example)}${text(w.source.suggested)}`:w.helpStage===3?text(w.source.skip):''}${button('data-pair-help',w.helpStage===0?'I’m stuck':w.helpStage===1?'Show a different example':w.helpStage===2?'Skip for now':'Read the hint again')}</section>`}${w?learning(r,w):''}</section>`;}
function treePage(v){return `<h2 id="pair-question" tabindex="-1">Follow a chance, then try a question</h2>${branchExplorer(v.root)}${question(v)}`;}
function resultChart(run,slots){const tally=pairTallies(run,slots);return `<div class="pairs-chart" role="img" aria-label="Completed pairs: ${tally.ss} two suns, ${tally.mixed} mixed, ${tally.mm} two moons, out of 15 trials.">${['ss','mixed','mm'].map(k=>`<div class="pairs-chart-row"><span>${category[k]}</span><div class="pairs-track"><span class="pairs-bar pairs-bar-${k}" data-pair-bar="${k}" data-value="${tally[k]}" style="width:${tally[k]/15*100}%"></span></div><strong>${tally[k]}</strong></div>`).join('')}<div class="pairs-chart-row" aria-hidden="true"><span></span><div class="pairs-axis">${Array.from({length:16},(_,i)=>`<span data-pair-tick="${i}" style="left:${i/15*100}%">${i%5===0?i:''}</span>`).join('')}</div><span></span></div></div>`;}
function resultsPage(v){const r=v.root,s=v.source,run=v.current,theory=pairTheory(s.slots,r.mode),count=pairCounts(s.slots);return `<h2 id="pair-question" tabindex="-1">What did the pairs show?</h2><p>Experiment bag: ${count.sun} ${esc(s.labels.sun)} and ${count.moon} ${esc(s.labels.moon)}. Rule: <strong>${ruleName(r.mode)}</strong>.</p>${v.readableRuns.length?`<div class="pairs-saved-runs" role="group" aria-label="Choose a recorded set">${v.readableRuns.map(({entry:x})=>button(`data-pair-run="${x.id}" aria-pressed="${run?.id===x.id}"`,`Set ${x.id}: ${ruleName(x.mode)} · ${x.pairs.length}/15`)).join('')}</div>`:'<p>No trial set has started. The tree and questions are open whenever you want them.</p>'}${run?`<h3>Set ${run.id}: ${run.pairs.length} of 15 complete pairs</h3>${resultChart(run,s.slots)}${run.pending!==null?'<p>One first seed is waiting for its second. That incomplete trial is not in these bars.</p>':''}<details class="pairs-ordered"><summary>See the recorded pair order</summary><ol>${run.pairs.map(p=>`<li>${esc(markName(s.slots[p.first],s.labels))}, then ${esc(markName(s.slots[p.second],s.labels))}</li>`).join('')}</ol></details>`:''}<table class="pairs-theory"><caption>Chances from the pictured bag and chosen rule</caption><thead><tr><th scope="col">Outcome</th><th scope="col">Exact chance</th>${theory.expected?'<th scope="col">Average per 15 trials</th>':''}</tr></thead><tbody>${['ss','mixed','mm'].map(k=>`<tr><th scope="row">${category[k]}</th><td data-pair-theory="${k}">${theory.categories[k]}/${theory.denominator}</td>${theory.expected?`<td data-pair-expected="${k}">${theory.expected[k]}</td>`:''}</tr>`).join('')}</tbody></table><p>Sun then moon: ${theory.paths.sm}/${theory.denominator}. Moon then sun: ${theory.paths.ms}/${theory.denominator}. Together, one of each: ${theory.categories.mixed}/${theory.denominator}.</p>${theory.expected?'<p>These averages describe many sets of 15. One set can look different; it is not supposed to match these counts exactly.</p>':'<p>This rule has its own exact chances. Whole-count averages for 15 trials are not shown here.</p>'}<p>Keeping the first seed out changes the second draw within that pair. Refilling before the next pair starts the same bag again. Earlier pairs do not make a mark “due.” These screen trials do not test a real bag or prove fairness.</p>${v.unreadableRuns.length?`<p>${v.unreadableRuns.length} earlier set(s) cannot be shown here. Their original records remain in <a href="#notes">your notes</a>.</p>`:''}${button('data-pair-page="draw"','Back to the waiting seeds',true)}`;}
export function pairsPage(state){const v=pairView(state);return `<div class="pairs-sheet" data-pairs-root lang="en"><header><a class="back" href="#numbers/seeds">Back to Seed Stall</a><h1>Keep it out</h1><p>The storm market has a mixed seed parcel. Draw two counters and investigate how the first draw changes the second.</p></header>${v.status==='missing'?`<h2 id="pair-question" tabindex="-1">Two seeds, two rules</h2>${bag(['sun','sun','moon','moon','moon','moon'])}<p>Try keeping the first seed out, then compare putting it back. Every trial starts with the same full bag.</p>${button('data-pair-start','Begin the investigation',true)}`:v.status!=='ready'?'<h2 id="pair-question" tabindex="-1">Your earlier experiment is kept safe</h2><p>This format cannot be edited here. Open notes to keep its original data; the original Seed Stall and other places stay open.</p><a href="#notes">Open notes</a>':`<nav class="pairs-pages" aria-label="Investigation pages">${['draw','tree','results'].map(p=>button(`data-pair-page="${p}" aria-current="${v.root.page===p?'page':'false'}"`,p==='draw'?'Draw pairs':p==='tree'?'Chance tree':'Results',v.root.page===p)).join('')}</nav>${modeButtons(v.root)}${v.root.page==='draw'?drawPage(v):v.root.page==='tree'?treePage(v):resultsPage(v)}`}<p id="pair-status" role="status" aria-live="polite" tabindex="-1"></p><footer><a href="#notes">Grown-up notes</a><a href="#numbers/seeds">Original Seed Stall</a></footer></div>`;}
export const pairsRefusal=()=>'<section class="pairs-sheet" data-pairs-root><h1 id="pair-question" tabindex="-1">Keep it out</h1><p>This page could not be opened and still leave your notebook ready to download. Your earlier work stays unchanged.</p><a href="#notes">Download notes</a> <a href="#numbers/seeds">Original Seed Stall</a><p id="pair-status" role="status" tabindex="-1"></p></section>';
export function pairsNotes(state){return Object.hasOwn(state,'seedPairs')?`<details class="panel"><summary>Keep it out: two-seed investigations</summary><p>Screen trials, predictions, checked questions and shown/requested help are separate records. A short run does not establish fairness, physical sampling, mastery or a particular reasoning method. Complete frozen question sources and historical outcomes remain as kept; unavailable siblings are retained below.</p><pre>${esc(JSON.stringify(state.seedPairs,null,2))}</pre></details>`:'';}
export function bindPairs(state,{save,render,focus,canExport,exposeFacts,explorerId,isActive}){const root=document.querySelector('[data-pairs-root]');if(!root)return;const route=location.hash,owner=explorerId?.(),bound=pairView(state),initial={status:bound.status,page:bound.root?.page,mode:bound.root?.mode,taskId:bound.root?.taskId,run:bound.current?.id};const o={canExport,exposeFacts};
 const live=el=>{if(!root.isConnected||!el.isConnected||!root.contains(el)||location.hash!==route||explorerId?.()!==owner||isActive&&!isActive())return false;const v=pairView(state);return v.status===initial.status&&v.root?.page===initial.page&&v.root?.mode===initial.mode&&v.root?.taskId===initial.taskId&&v.current?.id===initial.run;};
 const say=(msg,moveFocus=true)=>{const el=document.querySelector('#pair-status');if(el){el.textContent=msg;if(moveFocus)el.focus();}};
 const fail=()=>say('This change could not be kept safely. Earlier work and the waiting seeds stay here. Open notes or another place.');
 const redraw=(msg='',target='#pair-question')=>{stopSpeech();save();render();if(msg)say(msg,false);focus?.(document.querySelector(target)?target:'#pair-question');};
 const click=(selector,fn)=>root.querySelectorAll(selector).forEach(el=>el.addEventListener('click',()=>{if(live(el))fn(el);}));
 click('[data-pair-start]',()=>startPairs(state,o)?redraw():fail());
 click('[data-pair-page]',el=>setPairPage(state,el.dataset.pairPage,o)?redraw():fail());
 click('[data-pair-mode]',el=>setPairMode(state,el.dataset.pairMode,o)?redraw('',`[data-pair-mode="${el.dataset.pairMode}"]`):fail());
 click('[data-pair-begin], [data-pair-resume]',()=>beginPairRun(state,pairView(state).root.mode,o)?redraw('', '[data-pair-first]'):fail());
 click('[data-pair-run]',el=>selectPairRun(state,Number(el.dataset.pairRun),o)?redraw():fail());
 click('[data-pair-predict]',el=>choosePairPrediction(state,el.dataset.pairPredict==='none'?null:el.dataset.pairPredict,o)?redraw('',`[data-pair-predict="${el.dataset.pairPredict}"]`):fail());
 click('[data-pair-first]',()=>{const n=randomPairIndex(6);if(n===null)return say('A random screen draw is unavailable. Your bag and earlier results stay here.');if(!drawPairFirst(state,n,o))return fail();redraw('First seed recorded. Look at what is available for draw two.','[data-pair-second]');});
 click('[data-pair-second]',()=>{const v=pairView(state),remaining=pairRemaining(v.source.slots,v.root.mode,v.current.pending),n=randomPairIndex(remaining.indices.length);if(n===null)return say('A random screen draw is unavailable. The first seed stays waiting.');if(!drawPairSecond(state,n,o))return fail();redraw('Pair recorded. The full bag is ready for the next trial.','[data-pair-first]');});
 root.querySelector('[data-pair-task]')?.addEventListener('change',e=>{if(live(e.target)){if(!selectPairTask(state,e.target.value,o))return fail();redraw('', '#pair-task');}});
 root.querySelectorAll('[data-pair-draft]').forEach(el=>el.addEventListener('input',()=>{if(!live(el))return;if(!/^[0-9 ]{0,4}$/.test(el.value))return say('Use digits here. Other text is not saved or checked.',false);if(!setPairDraft(state,Number(el.dataset.pairDraft),el.value,o))return say('This edit could not be saved. Your previous draft stays kept.',false);save();}));
 click('[data-pair-option]',el=>setPairDraft(state,0,el.dataset.pairOption,o)?redraw('',`[data-pair-option="${el.dataset.pairOption}"]`):fail());
 click('[data-pair-check]',()=>{const w=pairView(state).work,raw=w.source.kind==='choice'?[w.draft[0]]:[...root.querySelectorAll('[data-pair-draft]')].map(el=>el.value),r=checkPair(state,raw,o);if(!r?.recorded)return say(r?.feedback||'This check could not be kept. Your earlier work stays here.');redraw(r.feedback,'#pair-status');});
 click('[data-pair-help]',()=>pairHelp(state,o)?redraw('Help changed. Your input and earlier checks stay kept.','[data-pair-help]'):fail());
 click('[data-pair-learn]',()=>advancePairLearn(state,o)?redraw('Next teaching line.','[data-pair-learn], [data-pair-fold]'):fail());
 click('[data-pair-fold]',el=>setPairFolded(state,el.dataset.pairFold==='true',o)?redraw('Teaching preference kept.','[data-pair-fold]'):fail());
 click('[data-pair-branch-stage]',el=>choosePairBranch(state,el.dataset.pairBranchStage,el.dataset.pairMark,o)?redraw('',`[data-pair-branch-stage="${el.dataset.pairBranchStage}"][data-pair-mark="${el.dataset.pairMark}"]`):fail());
 click('[data-pair-together]',()=>notePairSupport(state,'together',o)?redraw('Working together kept with this question.'):fail());
 root.querySelector('[data-pair-kept]')?.addEventListener('change',e=>{if(!live(e.target))return;const value=e.target.value,key=value==='none'?null:['first','latest'].includes(value)?value:Number(value);if(!selectPairCheck(state,key,o))return fail();redraw('Kept version selected.','#pair-kept');});
 root.querySelectorAll('[data-pair-audio] [data-speak]').forEach(el=>el.addEventListener('click',e=>{if(!live(el)){e.stopImmediatePropagation();return;}if(!notePairSupport(state,'audio',o)){e.stopImmediatePropagation();fail();return;}save();},true));
}
